-- mark overdue: Mark the open loans renewed three times as overdue
-- Changes exactly 2 Loan records of table loans: sets status to overdue, from open, and sets note to "Renewed three times", where renewals == 3.
-- Dry run: psql -v ON_ERROR_STOP=1 -v last_modified_by_user_id=... -v last_modified_by_user_nameid=... -f mark-overdue.sql
-- Apply: the same with -v apply=true. Without it every check runs against the data and the change is rolled back.
\set ON_ERROR_STOP on
\set QUIET on
\if :{?apply}
\else
\set apply false
\endif
\if :{?last_modified_by_user_id}
\else
DO $script$ BEGIN RAISE EXCEPTION 'mark-overdue.sql: the variable last_modified_by_user_id is not set; give it as psql -v last_modified_by_user_id=<last_modified_by_user_id> (VARCHAR(255))'; END $script$;
\endif
\if :{?last_modified_by_user_nameid}
\else
DO $script$ BEGIN RAISE EXCEPTION 'mark-overdue.sql: the variable last_modified_by_user_nameid is not set; give it as psql -v last_modified_by_user_nameid=<last_modified_by_user_nameid> (VARCHAR(255))'; END $script$;
\endif
BEGIN;
SET LOCAL specarch.apply = :'apply';
SET LOCAL specarch.last_modified_by_user_id = :'last_modified_by_user_id';
SET LOCAL specarch.last_modified_by_user_nameid = :'last_modified_by_user_nameid';
DO $script$
DECLARE
  found bigint;
  changed bigint;
BEGIN
  -- 1. Precondition: exactly 2 Loan records to change, locked until the end.
  SELECT count(*) INTO found FROM (SELECT 1 FROM loans WHERE status IN ('open')
    AND (renewals = 3)
    AND is_deleted = false FOR UPDATE) AS records;
  IF found <> 2 THEN
    RAISE EXCEPTION 'command mark overdue: % Loan records hold status open, renewals == 3, not deleted, and the change expects exactly 2; nothing was changed', found;
  END IF;
  -- 2. The change, under the same condition.
  UPDATE loans
  SET status = 'overdue',
      note = 'Renewed three times',
      last_modified_at = now(),
      last_modified_by_user_id = current_setting('specarch.last_modified_by_user_id', true)::VARCHAR,
      last_modified_by_user_nameid = current_setting('specarch.last_modified_by_user_nameid', true)::VARCHAR
  WHERE status IN ('open')
    AND (renewals = 3)
    AND is_deleted = false;
  GET DIAGNOSTICS changed = ROW_COUNT;
  -- 3. Postcondition: the exact count.
  IF changed <> 2 THEN
    RAISE EXCEPTION 'command mark overdue: the change wrote % Loan records, and exactly 2 was expected; another writer may have changed them after they were counted; nothing was changed', changed;
  END IF;
  -- 4. Dry run unless apply is true.
  IF current_setting('specarch.apply')::boolean THEN
    RAISE NOTICE 'command mark overdue: 2 Loan records changed; committing';
  ELSE
    RAISE NOTICE 'command mark overdue: dry run: 2 Loan records would change, and every check passed; rolling back. Run it again with -v apply=true to make the change';
  END IF;
END
$script$;
\if :apply
COMMIT;
\else
ROLLBACK;
\endif
